1	/**
2	 * The cypress-realworld-app Witness calibration driver.
3	 *
4	 * The journey's selectors, routes and backend category were declared from the
5	 * application's own Cypress specs, never yet read off the live DOM+backend.
6	 * Pinning a stateful journey before the live surface has been measured is what
7	 * the TinyTranslator/Super-Productivity rounds spent passes undoing. This drives
8	 * ONE lane of the built production-static output against the application's REAL
9	 * Express-over-lowdb backend — booted through the SAME generic serving path the
10	 * proof uses (`startStaticServer` + `startLiveBackend`), so the origin/CORS
11	 * coordination this driver exercises is the product's, not a bespoke copy — and
12	 * prints every measurement: the ordered steps and their refusals, the recorded
13	 * navigations, every request outcome bucketed by origin, and the tracked-event
14	 * counts.
15	 *
16	 * It publishes nothing, asserts nothing of its own, and is not part of any
17	 * receipt. Its only output is stdout. The backend is booted in the application's
18	 * own era runtime cell (Node 14.16.1), reseeded from its frozen snapshot before
19	 * the pass, exactly as the live-backend serving path reseeds.
20	 */
21	
22	import { readFileSync } from 'node:fs';
23	import { basename, join, resolve } from 'pathe';
24	import { box, runBoxes } from '@async/witness';
25	import { joinURL, parseHost, parseURL, stringifyParsedURL } from 'ufo';
26	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
27	import { WITNESS_REACT_CYPRESS_RWA_ACTOR } from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
28	import { type LiveBackendSpec, startLiveBackend } from '../witness/live-backend.ts';
29	import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
30	import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
31	import type { WitnessObservedRequestOutcome } from '../witness/playwright-host.ts';
32	import { startStaticServer } from '../witness/real-app-run.ts';
33	
34	const root = resolve(import.meta.dirname, '../../../..');
35	const workRoot = join(root, '.versionless/work/react-cypress-rwa');
36	const eraNodeBin = join(
37		root,
38		'.versionless/cache/react-cypress-rwa-runtime/node-v14.16.1-darwin-x64/bin',
39	);
40	const eraYarnBin = join(root, '.versionless/cache/react-cypress-rwa-baseline/npm-global/bin');
41	const chromiumExecutable = join(
42		root,
43		'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
44	);
45	
46	const laneStaticRoot = {
47		baseline: join(workRoot, 'baseline/build-run1'),
48		// The COMPLETE migrated Vite build (18 files, with index.html + hashed assets),
49		// byte-identical across two builds. The `build-vite-run1` sibling is a partial
50		// 6-file copy with no index.html and no assets, which serves a blank page —
51		// pointing the migrated lane at it would measure nothing, not a migration break.
52		migrated: join(workRoot, 'target/build-vite'),
53	} as const;
54	
55	/** The application source lane the backend server is spawned from. */
56	const backendLaneRoot = join(workRoot, 'baseline');
57	const BACKEND_PORT = 3001;
58	
59	const VIEWPORT = { width: 1280, height: 900 } as const;
60	
61	/** A decodable placeholder answered in-context for the app's S3 avatar SVGs. */
62	const NON_LOOPBACK_PLACEHOLDER_SVG =
63		'<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64"><rect width="64" height="64" fill="#dddddd"/></svg>';
64	
65	/**
66	 * The application's own live-backend declaration, exactly as the AppSpec declares
67	 * it: the app's server command, the loopback host and port its built SPA
68	 * addresses, and the CORS-origin port variable the harness injects the served
69	 * port into. The era-runtime PATH is the one application-specific fact the
70	 * calibration adds — the proof's executeRun path inherits the runtime cell a
71	 * different way — so the serving/origin coordination measured here is the
72	 * generic one.
73	 */
74	const backendSpec: LiveBackendSpec = {
75		command: 'yarn',
76		args: ['start:api'],
77		cwd: '.',
78		port: BACKEND_PORT,
79		host: 'localhost',
80		corsOriginPortEnv: ['REACT_APP_PORT'],
81		env: {
82			PATH: `${eraNodeBin}:${eraYarnBin}:${process.env.PATH ?? ''}`,
83			SKIP_YARN_COREPACK_CHECK: '1',
84		},
85		seed: { snapshot: 'data/database-seed.json', store: 'data/database.json' },
86		prepare: [{ from: 'scripts/mock-aws-exports.js', to: 'src/aws-exports.js' }],
87		health: { path: '/checkAuth', okStatus: [401] },
88		readyTimeoutMs: 45_000,
89	};
90	
91	const firstLine = (error: unknown): string =>
92		(error instanceof Error ? error.message : String(error)).split('\n')[0]!.trim();
93	
94	/** Swap the host of a `http://<host>:<port>` origin, keeping the bound port. */
95	function withHost(origin: string, host: string): string {
96		const port = parseHost(parseURL(origin).host ?? '').port ?? '';
97		return stringifyParsedURL({ protocol: 'http:', host: `${host}:${port}` });
98	}
99	
100	function bucketRequests(
101		outcomes: readonly WitnessObservedRequestOutcome[],
102		staticOrigin: string,
103		backendOrigin: string,
104	): unknown {
105		const backend = new Map<string, { count: number; statuses: number[] }>();
106		const other: Array<{ method: string; url: string; status: number | null }> = [];
107		let staticCount = 0;
108		for (const outcome of outcomes) {
109			if (outcome.url.startsWith(staticOrigin)) {
110				staticCount += 1;
111				continue;
112			}
113			if (outcome.url.startsWith(backendOrigin)) {
114				const parsed = parseURL(outcome.url.slice(backendOrigin.length));
115				const path = parsed.pathname || '/';
116				const key = `${outcome.method} ${path}`;
117				const existing = backend.get(key);
118				if (existing === undefined) backend.set(key, { count: 1, statuses: [outcome.status ?? 0] });
119				else {
120					existing.count += 1;
121					if (!existing.statuses.includes(outcome.status ?? 0))
122						existing.statuses.push(outcome.status ?? 0);
123				}
124				continue;
125			}
126			other.push({ method: outcome.method, url: outcome.url, status: outcome.status });
127		}
128		return {
129			staticCount,
130			backend: [...backend.entries()]
131				.map(([key, value]) => ({ endpoint: key, ...value }))
132				.sort((left, right) => left.endpoint.localeCompare(right.endpoint)),
133			other,
134		};
135	}
136	
137	function pageSummary(receiptPath: string): unknown {
138		const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
139			boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
140		};
141		const page = receipt.boxes?.[0]?.pages?.[0];
142		if (page === undefined) return null;
143		return {
144			navigations: (page.navigations as Array<{ url: string }> | undefined)?.map((navigation) => {
145				const parsed = parseURL(navigation.url);
146				return `${parsed.pathname}${parsed.hash}`;
147			}),
148			trackedEvents: Object.fromEntries(
149				Object.entries((page.trackedEvents as Record<string, unknown[]>) ?? {}).map(
150					([name, events]) => [name, events.length],
151				),
152			),
153			consoleErrors: (page.consoleMessages as Array<{ level: string }> | undefined)?.filter(
154				(message) => message.level === 'error',
155			).length,
156			pageErrors: (page.pageErrors as unknown[] | undefined)?.length,
157			failedRequests: page.failedRequests,
158		};
159	}
160	
161	export async function calibrateCypressRwaLane(lane: 'baseline' | 'migrated'): Promise<void> {
162		const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
163		const staticRoot = laneStaticRoot[lane];
164		const receiptDir = join(root, '.versionless/stage/witness-react-cypress-rwa-calibrate', lane);
165		// The generic serving path: bind the static server first, then boot the backend
166		// with the ephemeral served SPA port injected, and address the browser at the
167		// declared host so the document origin is the one the backend's CORS allow-list
168		// admits.
169		const staticServer = await startStaticServer(staticRoot, { profile: 'current-witness' });
170		const servedOrigin = withHost(staticServer.origin, backendSpec.host ?? '127.0.0.1');
171		const servedPort = Number(parseHost(parseURL(servedOrigin).host ?? '').port ?? '');
172		const backend = await startLiveBackend(backendLaneRoot, backendSpec, { spaPort: servedPort });
173		const host = createPlaywrightWitnessHost({
174			chromiumExecutable,
175			contextProfile: 'current-witness',
176			viewport: VIEWPORT,
177			// Every non-loopback request is answered in-context so nothing leaves the
178			// machine: the application's S3 avatar SVGs get a decodable placeholder image
179			// (so the page renders clean), anything else an empty 204. The host counts
180			// all of these as mockedNonLoopback and keeps successfulNonLoopback at 0.
181			transport: async (request) => {
182				if (request.pathname.endsWith('.svg'))
183					return {
184						action: 'fulfill',
185						status: 200,
186						contentType: 'image/svg+xml',
187						body: Buffer.from(NON_LOOPBACK_PLACEHOLDER_SVG),
188					};
189				return { action: 'fulfill', status: 204, contentType: 'text/plain', body: Buffer.alloc(0) };
190			},
191		});
192		const steps: Array<{ name: string; outcome: string }> = [];
193		let status = 'unknown';
194		let failure = '';
195		let receiptPath = '';
196		const definition = box(`cypress-rwa-calibrate-${lane}`, async (context) => {
197			// Signup is reached by a real load to `/signup`: clicking the signin page's
198			// signup link does not SPA-navigate under automation (measured), so the
199			// journey navigates there directly and the SPA index fallback renders the
200			// SignUpForm. Every anchor below is a settled-reaction wait, never a sleep.
201			const page = await context.browser.visit(joinURL(servedOrigin, '/signup'));
202			await page.trackEvents('click', 'input', 'change', 'keydown', 'mouseover');
203			const expectPage = context.expect.page;
204			const record = async (name: string, fn: () => Promise<void>): Promise<void> => {
205				try {
206					await fn();
207					steps.push({ name, outcome: 'ok' });
208				} catch (error: unknown) {
209					steps.push({ name, outcome: `FAIL: ${firstLine(error)}` });
210					throw error;
211				}
212			};
213			// Settled-reaction anchor: waits (bounded, event-driven) until the selector
214			// is in the DOM. A comma selector admits either of two settled shapes — a
215			// populated list or the app's own empty-list marker — for a feed whose
216			// content depends on the actor's relationships.
217			const anchor = (name: string, selector: string): Promise<void> =>
218				record(`anchor ${name}`, () => expectPage.exists(page, selector));
219			const type = (name: string, selector: string, text: string): Promise<void> =>
220				record(`type ${name}`, () => page.type(selector, text, { redact: false }));
221			const click = (name: string, selector: string): Promise<void> =>
222				record(`click ${name}`, () => page.click(selector, { timeoutMs: 8_000 }));
223	
224			// The MUI `data-test` on signup/signin/bankaccount/transaction-create sits on
225			// the TextField ROOT, so the real <input> is `[data-test=…] input`; the
226			// settings and peer-search fields carry `data-test` on the <input> itself
227			// (inputProps), so they are addressed without the ` input` descendant. Both
228			// facts are measured against the live DOM.
229	
230			// Sign up as a fresh NON-seed actor.
231			await anchor('signup-form', '[data-test=signup-first-name] input');
232			await type('signup-first', '[data-test=signup-first-name] input', actor.firstName);
233			await type('signup-last', '[data-test=signup-last-name] input', actor.lastName);
234			await type('signup-username', '[data-test=signup-username] input', actor.username);
235			await type('signup-password', '[data-test=signup-password] input', actor.password);
236			await type('signup-confirm', '[data-test=signup-confirmPassword] input', actor.password);
237			await click('signup-submit', '[data-test=signup-submit]');
238	
239			// Sign in as it.
240			await anchor('back-to-signin', '[data-test=signin-username] input');
241			await type('signin-username', '[data-test=signin-username] input', actor.username);
242			await type('signin-password', '[data-test=signin-password] input', actor.password);
243			await click('signin-submit', '[data-test=signin-submit]');
244	
245			// Onboarding — the app's first-bank-account dialog (POST /graphql).
246			await anchor('onboarding-dialog', '[data-test=user-onboarding-next]');
247			await click('onboarding-next-1', '[data-test=user-onboarding-next]');
248			await anchor('bank-form', '[data-test=bankaccount-bankName-input] input');
249			await type('bank-name', '[data-test=bankaccount-bankName-input] input', 'Versionless Bank');
250			await type('bank-routing', '[data-test=bankaccount-routingNumber-input] input', '987654321');
251			await type('bank-account', '[data-test=bankaccount-accountNumber-input] input', '123456789');
252			await click('bank-submit', '[data-test=bankaccount-submit]');
253			await anchor('onboarding-done', '[data-test=user-onboarding-next]');
254			await click('onboarding-next-2', '[data-test=user-onboarding-next]');
255	
256			// Settings write — a fresh actor has no email/phone, so the form is invalid
257			// and Save stays disabled until both are filled; filling them and saving is
258			// the mutating PATCH /users/{created-user-id} the journey proves.
259			await anchor('home', '[data-test=sidenav-user-settings]');
260			await click('nav-settings', '[data-test=sidenav-user-settings]');
261			await anchor('settings-form', '[data-test=user-settings-email-input]');
262			await type('settings-email', '[data-test=user-settings-email-input]', 'prover@versionless.test');
263			await type('settings-phone', '[data-test=user-settings-phoneNumber-input]', '6155551234');
264			await click('settings-submit', '[data-test=user-settings-submit]');
265	
266			// Money movement — search a peer (its handle is captured and normalized, never
267			// recorded), send a payment the backend mints an id for (POST /transactions).
268			await anchor('after-settings', '[data-test=nav-top-new-transaction]');
269			await click('new-transaction', '[data-test=nav-top-new-transaction]');
270			await anchor('peer-search', '[data-test=user-list-search-input]');
271			await type('search-peer', '[data-test=user-list-search-input]', 'a');
272			await anchor('peer-results', '[data-test^=user-list-item-]');
273			await click('pick-peer', '[data-test^=user-list-item-]');
274			await anchor('amount-form', '[data-test=transaction-create-amount-input] input');
275			await type('amount', '[data-test=transaction-create-amount-input] input', '15');
276			await type(
277				'description',
278				'[data-test=transaction-create-description-input] input',
279				'versionless-proof-payment',
280			);
281			await click('submit-payment', '[data-test=transaction-create-submit-payment]');
282	
283			// The minted transaction round-trips lowdb into the actor's personal feed, and
284			// the balance settles — the substantive stateful assertion of the journey.
285			await anchor('payment-settled', '[data-test=sidenav-home]');
286			await click('home', '[data-test=sidenav-home]');
287			await click('personal-tab', '[data-test=nav-personal-tab]');
288			await anchor('personal-feed', '[data-test=transaction-list]');
289			await record('minted-tx-in-feed', () =>
290				expectPage.bodyText(page, { contains: 'versionless-proof-payment' }),
291			);
292			await record('balance-settled', () =>
293				expectPage.visible(page, '[data-test=sidenav-user-balance]'),
294			);
295	
296			// Feed filter — the three feeds the app ships. Contacts is empty for a fresh
297			// actor, so its settled shape is the app's own empty-list marker.
298			await click('public-tab', '[data-test=nav-public-tab]');
299			await anchor('public-feed', '[data-test=transaction-list]');
300			await click('contacts-tab', '[data-test=nav-contacts-tab]');
301			await anchor('contacts-feed', '[data-test=transaction-list], [data-test=empty-list-header]');
302			await click('personal-tab-2', '[data-test=nav-personal-tab]');
303			await anchor('personal-feed-2', '[data-test=transaction-list]');
304	
305			// Notifications — read the app's own notification feed (GET /notifications).
306			await click('nav-notifications', '[data-test=sidenav-notifications]');
307			await anchor(
308				'notifications-settled',
309				'[data-test=notifications-list], [data-test=empty-list-header]',
310			);
311	
312			await record('tracked-events', () =>
313				expectPage.outcome(page, {
314					events: {
315						click: { atLeast: 10 },
316						input: { atLeast: 8 },
317						keydown: { atLeast: 8 },
318					},
319				}),
320			);
321	
322			await context.receipt.capture('calibration-complete');
323		});
324		try {
325			const result = await runBoxes({
326				root: staticRoot,
327				boxes: [
328					{
329						file: join(staticRoot, 'versionless-runtime.box.ts'),
330						relativeFile: 'versionless-runtime.box.ts',
331						exportName: 'default',
332						box: definition,
333					},
334				],
335				receiptDir,
336				assertionTimeoutMs: 8_000,
337				fileSystem: witnessNodeFileSystem,
338				browser: host.browser,
339				headless: true,
340			});
341			status = result.status;
342			failure = result.boxes[0]?.error?.message ?? '';
343			receiptPath = result.receiptPath;
344		} finally {
345			await staticServer.close();
346			await backend.close();
347		}
348		process.stdout.write(
349			`${canonicalize({
350				lane,
351				status,
352				failure,
353				staticOrigin: servedOrigin,
354				backendOrigin: backend.origin,
355				steps,
356				locality: host.locality(),
357				requests: bucketRequests(host.requestOutcomes(), servedOrigin, backend.origin),
358				page: receiptPath === '' ? null : pageSummary(receiptPath),
359			})}\n`,
360		);
361	}
362	
363	export async function main(args = process.argv.slice(2)): Promise<void> {
364		const lane = args[0];
365		if (lane !== 'baseline' && lane !== 'migrated')
366			throw new Error('cypress-rwa calibration requires a lane: baseline or migrated');
367		await calibrateCypressRwaLane(lane);
368	}
369	
370	if (basename(process.argv[1] ?? '') === 'react-cypress-rwa-calibrate-run.ts')
371		main().catch((error: unknown) => {
372			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
373			process.exitCode = 1;
374		});
