458				!expectedRuns.delete(key) ||
459				run.app !== REACT_CYPRESS_RWA_APPLICATION ||
460				run.framework !== 'react' ||
461				run.result !== 'pass' ||
462				run.cleanPage !== true ||
463				run.successfulNonLoopback !== 0 ||
464				run.witnessRecord.pageErrors !== 0 ||
465				!Array.isArray(run.interactions) ||
466				run.interactions.length === 0 ||
467				!Array.isArray(run.assertions) ||
468				run.assertions.length === 0 ||
469				!exact(run.routes, WITNESS_REACT_CYPRESS_RWA_ROUTES) ||
470				!exact(run.placeholders, WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS) ||
471				run.semanticDigest !== witnessReactCypressRwaRawDigest(run) ||
472				run.behaviorDigest !== witnessReactCypressRwaBehaviorDigest(run)
473			)
474				throw new Error(`Cypress RWA Witness run differs: ${key}`);
475			assertServedStatic(run.servedStatic, key);
476			assertLoopbackBackend(run.loopbackBackend, key);
477			assertRedaction(run, key);
478			const priorSemantic = semanticByLane.get(run.lane);
479			if (priorSemantic !== undefined && priorSemantic !== run.semanticDigest)
480				throw new Error(`Cypress RWA Witness pass-twice semantic digest differs: ${run.lane}`);
481			semanticByLane.set(run.lane, run.semanticDigest);
482			behaviors.add(run.behaviorDigest);
483		}
484		if (
485			expectedRuns.size !== 0 ||
486			behaviors.size !== 1 ||
487			receipt.determinism?.reseededFromSnapshotBeforeEachPass !== true ||
488			receipt.determinism.mintedValuesPlaceholdered !== true ||
489			receipt.determinism.rule !== WITNESS_JOURNEY_PLACEHOLDER_RULE ||
490			receipt.redaction?.policy !== 'no-seed-usernames-passwords-or-pii' ||
491			receipt.redaction.actorIsNonSeedCorpusIdentity !== true ||
492			!exact(receipt.redaction.forbiddenMarkers, WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS) ||
493			receipt.mutation?.intendedFailure !== true ||
494			receipt.mutation.failure !== 'witness-semantic-assertion' ||
495			receipt.mutation.lane !== 'migrated' ||
496			receipt.mutation.restoredByteIdentically !== true ||
497			receipt.mutation.restoredRun !== 'pass' ||
498			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
499			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
500			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
501			receipt.locality?.mode !== 'live-loopback-backend' ||
502			receipt.locality.successfulNonLoopback !== 0 ||
503			receipt.locality.osWideIsolation !== false ||
504			receipt.locality.rule !== WITNESS_LOOPBACK_BACKEND_RULE ||
505			!Array.isArray(receipt.nonclaims) ||
506			receipt.nonclaims.length === 0 ||
507			receipt.integrity?.algorithm !== 'sha256' ||
508			receipt.integrity.canonicalDigest !== witnessReactCypressRwaDigest(receipt)
509		)
510			throw new Error('Cypress RWA Witness integrity or determinism differs');
511		return receipt;
512	}
513	
514	export function witnessReactCypressRwaAggregateMember(digestValue: string) {
515		return {
516			id: 'witness-react-cypress-rwa',
517			framework: 'react',
518			track: 'production-readiness-direct-witness-live-backend-create-react-app-to-vite8',
519			bundler: 'webpack-4.44.2-to-vite-8.0.16',
520			backend: 'live-loopback',
