18	/**
19	 * A live first-party backend an {@link AppSpec} declares.
20	 *
21	 * Everything here is the application's own — its server command, the loopback
22	 * port its SPA was built against, the frozen seed snapshot it ships, and the
23	 * mutable store the server reads. The harness knows nothing app-specific: it
24	 * copies the declared snapshot over the declared store, runs the declared
25	 * command from the declared working directory, and waits for the declared
26	 * health probe. A future stateful application inherits this by declaring the
27	 * same fields; there is no branch on application identity anywhere in the
28	 * serving path.
29	 */
30	export type LiveBackendSpec = {
31		/** The application's own server executable, run from its lane root. */
32		command: string;
33		args: readonly string[];
34		/** The server's working directory, relative to the lane root. */
35		cwd?: string;
36		/** Extra environment the application's server reads, merged over the inherited environment. */
37		env?: Readonly<Record<string, string>>;
38		/**
39		 * The loopback port the server binds. It is fixed by the application because
40		 * its built SPA addresses it; the harness does not choose it, it serves it.
41		 */
42		port: number;
43		/**
44		 * The loopback host name the built SPA addresses — both the host the browser
45		 * must be served the document from and the host baked into the SPA's absolute
46		 * backend URL. A production build may hard-code `http://localhost:<port>` for
47		 * its API and enforce a CORS allow-origin pinned to `localhost`, so serving the
48		 * document from `127.0.0.1` would make every credentialed request cross-origin
49		 * and CORS-rejected. Declaring `localhost` here binds the backend origin and
50		 * the served document under that name. Omitted, the host is `127.0.0.1` —
51		 * exactly the origin every origin-agnostic loopback backend already used, so a
52		 * backend that omits it is served exactly as it was before this field existed.
53		 */
54		host?: string;
55		/**
56		 * The environment variable name(s) the application's server reads to learn the
57		 * served SPA port when it builds its CORS allow-origin. The static SPA port is
58		 * ephemeral, so the harness injects the actual served port into each named
59		 * variable before spawning the backend; a credentialed request from the served
60		 * origin is then on the backend's allow-list rather than CORS-rejected. Omitted,
61		 * no port is injected and the backend's own environment decides its origin
62		 * policy, unchanged.
63		 */
64		corsOriginPortEnv?: readonly string[];
65		/**
66		 * The deterministic re-seed mechanism: the frozen seed snapshot and the
67		 * mutable store it is copied over before every pass. Both are lane-relative,
68		 * so the evidence names files rather than the machine.
69		 */
70		seed: { snapshot: string; store: string };
71		/**
72		 * Additional lane-relative file copies the application requires before its
73		 * server boots (for example a committed mock-config file the build expects).
74		 * Applied on every re-seed so a pass never inherits a previous pass's copy.
75		 */
76		prepare?: readonly { from: string; to: string }[];
77		/**
78		 * The readiness probe: an origin-relative path the server answers once it is
79		 * up, and the set of statuses that count as up. An auth-gated route that
80		 * answers 401 before any session exists is a server that is up, so the set is
81		 * declared rather than assumed to be 200.
82		 */
83		health: { path: string; okStatus: readonly number[] };
84		/** How long to wait for the health probe to pass before giving up. */
85		readyTimeoutMs?: number;
86	};
87	
88	/** A running live backend bound to a second bounded loopback origin. */
89	export type LiveBackendHandle = {
90		/**
91		 * The loopback origin the application's SPA addresses its server at —
92		 * `http://<host>:<port>`, where the host is the declared {@link
93		 * LiveBackendSpec.host} (`127.0.0.1` by default). It is the origin the page's
94		 * backend requests are bucketed against, so it must be the exact origin the
95		 * built SPA calls, not merely the interface the server binds.
96		 */
97		origin: string;
98		/**
99		 * Restore the frozen seed and restart the server, so the next pass starts from
100		 * exactly the declared snapshot rather than inheriting the mutations the
101		 * previous pass made. A lowdb store is read at boot, so a re-seed is a
102		 * restart, not a live file swap.
103		 */
104		reseed(): Promise<void>;
105		/** Stop the server and release the loopback port. */
106		close(): Promise<void>;
107	};
108	
109	const DEFAULT_READY_TIMEOUT_MS = 30_000;
110	const HEALTH_POLL_INTERVAL_MS = 250;
111	
112	function loopbackOrigin(host: string, port: number): string {
113		return stringifyParsedURL({ protocol: 'http:', host: `${host}:${port}` });
114	}
115	
116	/**
117	 * The origin the SPA addresses the backend at: the declared loopback host and
118	 * the bound port. `localhost`, `127.0.0.1` and `[::1]` are all loopback names,
119	 * and which one a built SPA hard-codes is the application's own fact, so the
120	 * host is read from the declaration rather than fixed here. It defaults to
121	 * `127.0.0.1`, the origin every origin-agnostic backend already used. Exported
122	 * so the coordination between this origin and the loopback-backend bucketing can
123	 * be checked without spawning a server.
124	 */
125	export function liveBackendOrigin(spec: LiveBackendSpec): string {
126		return loopbackOrigin(spec.host ?? '127.0.0.1', spec.port);
127	}
128	
129	/**
130	 * The environment the harness injects for the served SPA port. A backend that
131	 * declares no CORS-origin port variable gets nothing injected; one that does
132	 * gets the actual ephemeral served port in each named variable, so its own CORS
133	 * allow-origin resolves to the origin the browser is really served from. It is
134	 * an error to declare the variables without supplying a served port, because
135	 * the whole point of the declaration is to carry that port. Exported so the
136	 * injection can be unit-tested without spawning a server.
137	 */
138	export function liveBackendCorsEnv(
139		spec: LiveBackendSpec,
140		served: { spaPort: number } | null,
141	): Record<string, string> {
142		const names = spec.corsOriginPortEnv ?? [];
143		if (names.length === 0) return {};
144		if (served === null)
145			throw new Error(
146				'live backend declares a CORS-origin port variable but no served SPA port was supplied',
147			);
148		return Object.fromEntries(names.map((name) => [name, String(served.spaPort)]));
149	}
150	
151	async function probeHealth(origin: string, path: string): Promise<number | null> {
152		return await new Promise<number | null>((resolvePromise) => {
153			const request = get(`${origin}${path}`, (response) => {
154				const status = response.statusCode ?? null;
155				response.resume();
156				resolvePromise(status);
157			});
158			request.setTimeout(HEALTH_POLL_INTERVAL_MS, () => request.destroy());
159			request.on('error', () => resolvePromise(null));
160		});
161	}
162	
163	async function delay(ms: number): Promise<void> {
164		await new Promise<void>((resolvePromise) => {
165			setTimeout(resolvePromise, ms);
166		});
167	}
168	
169	async function applySeed(laneRoot: string, spec: LiveBackendSpec): Promise<void> {
170		const copies = [
171			{ from: spec.seed.snapshot, to: spec.seed.store },
172			...(spec.prepare ?? []),
173		];
174		for (const copy of copies) {
175			const to = resolve(laneRoot, copy.to);
176			await mkdir(dirname(to), { recursive: true });
177			await copyFile(resolve(laneRoot, copy.from), to);
178		}
179	}
180	
181	function spawnBackend(
182		laneRoot: string,
183		spec: LiveBackendSpec,
184		injectedEnv: Readonly<Record<string, string>>,
185	): ChildProcess {
186		return spawn(spec.command, [...spec.args], {
187			cwd: resolve(laneRoot, spec.cwd ?? '.'),
188			env: { ...process.env, ...spec.env, ...injectedEnv, PORT: String(spec.port) },
189			stdio: 'ignore',
190		});
191	}
192	
193	async function waitForHealth(origin: string, spec: LiveBackendSpec): Promise<void> {
194		const deadline = Date.now() + (spec.readyTimeoutMs ?? DEFAULT_READY_TIMEOUT_MS);
195		const okStatus = new Set(spec.health.okStatus);
196		while (Date.now() < deadline) {
197			const status = await probeHealth(origin, spec.health.path);
198			if (status !== null && okStatus.has(status)) return;
199			await delay(HEALTH_POLL_INTERVAL_MS);
200		}
201		throw new Error(`live backend did not become healthy at ${origin}${spec.health.path}`);
202	}
203	
204	async function stopProcess(child: ChildProcess): Promise<void> {
205		if (child.exitCode !== null || child.signalCode !== null) return;
206		await new Promise<void>((resolvePromise) => {
207			child.once('exit', () => resolvePromise());
208			child.kill('SIGTERM');
209			setTimeout(() => {
210				if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
211			}, 2_000);
212		});
213	}
214	
215	/**
216	 * Spawns the application's own server on a second bounded loopback origin,
217	 * having first restored its frozen seed. Generic: every value comes from the
218	 * declared {@link LiveBackendSpec}, so a stateful application is served by
219	 * declaring one, not by teaching the harness its name.
220	 *
221	 * `served` carries the ephemeral SPA port the harness bound the static server
222	 * to. A backend that declares {@link LiveBackendSpec.corsOriginPortEnv} needs it
223	 * — the served origin's port is not known until the static server is up — while
224	 * an origin-agnostic backend ignores it. The health probe always targets
225	 * `127.0.0.1` (the loopback interface is reachable there whatever host the SPA
226	 * addresses), while the returned origin is the declared-host origin the SPA
227	 * actually calls.
228	 */
229	export async function startLiveBackend(
230		laneRoot: string,
231		spec: LiveBackendSpec,
232		served: { spaPort: number } | null = null,
233	): Promise<LiveBackendHandle> {
234		const origin = liveBackendOrigin(spec);
235		const healthOrigin = loopbackOrigin('127.0.0.1', spec.port);
236		const injectedEnv = liveBackendCorsEnv(spec, served);
237		let child: ChildProcess | null = null;
238		const bringUp = async (): Promise<void> => {
239			if (child !== null) await stopProcess(child);
240			await applySeed(laneRoot, spec);
241			child = spawnBackend(laneRoot, spec, injectedEnv);
242			await waitForHealth(healthOrigin, spec);
243		};
244		await bringUp();
245		return {
246			origin,
247			reseed: bringUp,
248			close: async () => {
249				if (child !== null) await stopProcess(child);
250				child = null;
251			},
252		};
253	}
254	
255	function originRelativePath(url: string, origin: string): string {
256		const rest = url.slice(origin.length);
257		const parsed = parseURL(rest.startsWith('/') ? rest : `/${rest}`);
258		return parsed.pathname || '/';
259	}
260	
261	const backendKey = (method: string, path: string): string => `${method} ${path}`;
262	
263	/**
264	 * Builds the live-backend request inventory for one run from the observed
265	 * request outcomes and the two bounded loopback origins.
266	 *
267	 * The static origin is ignored here — it has its own byte inventory — and every
268	 * request to the backend origin is counted in its own category by method and
269	 * origin-relative path. The non-loopback discipline is unweakened: a request to
270	 * anything that is neither loopback origin fails the run, and a backend endpoint
271	 * the journey did not declare lands in `outsideCategory`, which must stay empty.
272	 * `successfulNonLoopback` is fixed at 0 by construction, because nothing counted
273	 * here left the machine.
274	 */
275	export function buildLoopbackBackendInventory(
276		requestOutcomes: readonly WitnessObservedRequestOutcome[],
277		staticOrigin: string,
278		origin: string,
279		category: readonly WitnessLoopbackBackendCategoryEntry[],
280	): WitnessLoopbackBackendInventory {
281		const declared = new Set(category.map((entry) => backendKey(entry.method, entry.path)));
282		if (declared.size !== category.length)
283			throw new Error('live backend inventory repeats a declared endpoint');
284		const observations = new Map<string, WitnessLoopbackBackendObservation>();
285		const outside: WitnessLoopbackBackendCategoryEntry[] = [];
286		for (const outcome of requestOutcomes) {
287			if (outcome.url.startsWith(staticOrigin)) continue;
288			if (!outcome.url.startsWith(origin)) {
289				if (!isWitnessLoopbackUrl(outcome.url))
290					throw new Error(`live backend run reached a non-loopback origin: ${outcome.url}`);
291				throw new Error(`live backend run reached an unexpected loopback origin: ${outcome.url}`);
292			}
293			const path = originRelativePath(outcome.url, origin);
294			const key = backendKey(outcome.method, path);
295			if (!declared.has(key)) {
296				if (!outside.some((entry) => backendKey(entry.method, entry.path) === key))
297					outside.push({ method: outcome.method, path });
298				continue;
299			}
300			const existing = observations.get(key);
301			const status = outcome.status ?? 0;
302			if (existing === undefined)
303				observations.set(key, {
304					method: outcome.method,
305					path,
306					requests: 1,
307					statuses: [status],
308				});
309			else {
310				existing.requests += 1;
311				if (!existing.statuses.includes(status)) existing.statuses.push(status);
312			}
313		}
314		if (outside.length > 0)
315			throw new Error(
316				`live backend requests outside the declared category: ${JSON.stringify(outside)}`,
317			);
318		const observed = [...observations.values()].map((observation) => ({
319			...observation,
320			statuses: [...observation.statuses].sort((left, right) => left - right),
321		}));
322		observed.sort((left, right) =>
323			backendKey(left.method, left.path).localeCompare(backendKey(right.method, right.path)),
324		);
325		const observedKeys = new Set(observed.map((entry) => backendKey(entry.method, entry.path)));
326		const absent = category
327			.filter((entry) => !observedKeys.has(backendKey(entry.method, entry.path)))
328			.map((entry) => ({ method: entry.method, path: entry.path }));
329		return {
330			policy: 'live-first-party-loopback-backend',
331			backend: 'live-loopback',
332			rule: WITNESS_LOOPBACK_BACKEND_RULE,
333			category: category.map((entry) => ({ method: entry.method, path: entry.path })),
334			observed,
335			absent,
336			outsideCategory: [],
337			admitted: observed.reduce((sum, entry) => sum + entry.requests, 0),
338			successfulNonLoopback: 0,
339		};
340	}
341	
342	/** One minted value captured from a run, paired with the token that replaces it. */
343	export type WitnessCapturedMint = WitnessJourneyPlaceholderDeclaration & { value: string };
344	
345	/**
346	 * Replaces every occurrence of each declared minted value with its stable
347	 * placeholder token throughout a run's recorded journey evidence.
348	 *
349	 * This is the generic form of the HospitalRun `{created-patient-id}` idiom: a
350	 * stateful journey mints identifiers its server decides, captures them, and
351	 * declares the token each is normalized to. Only the captured values are
352	 * touched — the shape of the evidence is untouched — so two passes that minted
353	 * different identifiers normalize to identical evidence while a dropped step
354	 * still differs. Longer values are substituted first so a value that is a
355	 * substring of another cannot be half-replaced, and a token that already appears
356	 * literally in the un-normalized evidence is rejected as ambiguous.
357	 */
358	export function normalizeJourneyPlaceholders<T>(evidence: T, mints: readonly WitnessCapturedMint[]): T {
359		if (mints.length === 0) return structuredClone(evidence);
360		const serialized = JSON.stringify(evidence);
361		if (serialized === undefined)
362			throw new Error('journey evidence is not serializable for placeholder normalization');
363		let text = serialized;
364		const ordered = [...mints].sort((left, right) => right.value.length - left.value.length);
365		for (const mint of ordered) {
366			if (mint.value.length === 0 || mint.token.length === 0)
367				throw new Error('journey placeholder declares an empty value or token');
368			if (text.includes(mint.token))
369				throw new Error(`journey placeholder token collides with recorded evidence: ${mint.token}`);
370		}
371		for (const mint of ordered) text = text.split(mint.value).join(mint.token);
372		return JSON.parse(text) as T;
373	}
374	
375	/** The stateful application names this serving path admits, re-exported for callers. */
376	export const LIVE_BACKEND_STATEFUL_NAMES = WITNESS_REAL_APP_STATEFUL_NAMES;
377

